	// 一张极简有效 PNG：纯色 4x3，由 base64 提供模板后按颜色重写太繁琐，
	// 这里直接动态生成 1x1 纯色 PNG 的 IHDR/IDAT 并不直观，
	// 因此用内置模板（下方 data）+ 颜色参数构造太复杂时退化为固定灰底。
	_ = hexColor
	data, _ := base64.StdEncoding.DecodeString(pngTemplate)
	return data
}

// 1x1 灰色 PNG 模板（占位用）
const pngTemplate = "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mP8z8BQDwAEhQGAhKmMIQAAAABJRU5ErkJggg=="

