:root {
  --ink: #4a3f35;
  --ink-soft: #7a6b5d;
  --paper: #f7f1e6;
  --paper-warm: #f1e7d3;
  --card: #fffdf8;
  --accent: #c2683f;       /* 朱砂红 */
  --accent-dark: #a4522e;
  --teal: #5b8378;         /* 旧照片青 */
  --gold: #c9a24f;         /* 硬币金 */
  --line: #e3d8c4;
  --shadow: 0 6px 24px rgba(90, 70, 45, 0.10);
  --radius: 14px;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

html, body, #app { height: 100%; }

body {
  font-family: "PingFang SC", "Microsoft YaHei", "Noto Sans SC", sans-serif;
  color: var(--ink);
  background:
    radial-gradient(1200px 500px at 80% -10%, rgba(201, 162, 79, 0.12), transparent),
    radial-gradient(900px 500px at -10% 110%, rgba(91, 131, 120, 0.10), transparent),
    var(--paper);
  line-height: 1.7;
}

a { color: var(--accent); text-decoration: none; }

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  border-radius: 10px;
  padding: 9px 20px;
  font-size: 14px;
  transition: transform .12s ease, box-shadow .12s ease, background .2s;
}
button:active { transform: scale(.97); }
button:disabled { opacity: .5; cursor: not-allowed; }

.btn-primary {
  background: var(--accent);
  color: #fff;
}
.btn-primary:hover:not(:disabled) { background: var(--accent-dark); }

.btn-ghost {
  background: transparent;
  color: var(--accent);
  border: 1px solid var(--accent);
}
.btn-ghost:hover:not(:disabled) { background: rgba(194, 104, 63, .08); }

.btn-teal { background: var(--teal); color: #fff; }
.btn-teal:hover:not(:disabled) { background: #4c6f66; }

.card {
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
}

.input, .textarea, select.input {
  width: 100%;
  padding: 10px 14px;
  border: 1px solid var(--line);
  border-radius: 10px;
  font-size: 14px;
  font-family: inherit;
  background: #fffdf9;
  color: var(--ink);
  outline: none;
  transition: border-color .2s;
}
.input:focus, .textarea:focus { border-color: var(--accent); }
.textarea { resize: vertical; min-height: 90px; }

.tag {
  display: inline-block;
  padding: 2px 10px;
  border-radius: 999px;
  font-size: 12px;
  background: var(--paper-warm);
  color: var(--ink-soft);
}
.tag-open { background: rgba(91,131,120,.14); color: var(--teal); }
.tag-done { background: rgba(201,162,79,.18); color: #9a7a2e; }

.coin {
  color: #9a7a2e;
  font-weight: 600;
  white-space: nowrap;
}
.coin::before {
  content: "◉";
  color: var(--gold);
  margin-right: 3px;
}

.muted { color: var(--ink-soft); font-size: 13px; }

.toast {
  position: fixed;
  top: 24px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--ink);
  color: #fff;
  padding: 10px 22px;
  border-radius: 10px;
  font-size: 14px;
  z-index: 999;
  box-shadow: 0 8px 30px rgba(0,0,0,.25);
  animation: toast-in .25s ease;
}
.toast.error { background: #a4453a; }
@keyframes toast-in {
  from { opacity: 0; transform: translate(-50%, -12px); }
  to { opacity: 1; transform: translate(-50%, 0); }
}

.modal-mask {
  position: fixed;
  inset: 0;
  background: rgba(60, 48, 36, .45);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 100;
  padding: 20px;
}
.modal {
  background: var(--card);
  border-radius: 16px;
  width: 100%;
  max-width: 560px;
  max-height: 88vh;
  overflow-y: auto;
  padding: 28px;
  box-shadow: 0 20px 60px rgba(0,0,0,.3);
}
.modal h3 { margin-bottom: 18px; font-size: 19px; }
.form-row { margin-bottom: 14px; }
.form-row label {
  display: block;
  font-size: 13px;
  color: var(--ink-soft);
  margin-bottom: 5px;
}
.modal-actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  margin-top: 20px;
}

.photo-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(140px, 1fr));
  gap: 8px;
  margin-top: 10px;
}
.photo-grid img {
  width: 100%;
  height: 110px;
  object-fit: cover;
  border-radius: 8px;
  border: 1px solid var(--line);
  cursor: zoom-in;
}

.empty {
  text-align: center;
  padding: 60px 20px;
  color: var(--ink-soft);
}
.empty .big-font { font-size: 40px; margin-bottom: 10px; }

