.tag-done { background: rgba(201,162,79,.18); color: #9a7a2e; }

.coin {
  color: #9a7a2e;
  font-weight: 600;
  white-space: nowrap;
}
.coin::before {
  content: "◉";
  color: var(--gold);
  margin-right: 3px;
}

.muted { color: var(--ink-soft); font-size: 13px; }

.toast {
  position: fixed;
  top: 24px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--ink);
  color: #fff;
  padding: 10px 22px;
  border-radius: 10px;
  font-size: 14px;
  z-index: 999;
  box-shadow: 0 8px 30px rgba(0,0,0,.25);
  animation: toast-in .25s ease;
}
.toast.error { background: #a4453a; }
@keyframes toast-in {
  from { opacity: 0; transform: translate(-50%, -12px); }
  to { opacity: 1; transform: translate(-50%, 0); }
}

.modal-mask {
  position: fixed;
  inset: 0;
  background: rgba(60, 48, 36, .45);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 100;
  padding: 20px;
}
.modal {
  background: var(--card);
  border-radius: 16px;
  width: 100%;
  max-width: 560px;
  max-height: 88vh;
  overflow-y: auto;
  padding: 28px;
  box-shadow: 0 20px 60px rgba(0,0,0,.3);
}
.modal h3 { margin-bottom: 18px; font-size: 19px; }
.form-row { margin-bottom: 14px; }
.form-row label {
  display: block;
  font-size: 13px;
  color: var(--ink-soft);
  margin-bottom: 5px;
}
.modal-actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  margin-top: 20px;
}

.photo-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(140px, 1fr));
  gap: 8px;
  margin-top: 10px;
}
.photo-grid img {
  width: 100%;
  height: 110px;
  object-fit: cover;
  border-radius: 8px;
  border: 1px solid var(--line);
  cursor: zoom-in;
}

.empty {
  text-align: center;
  padding: 60px 20px;
  color: var(--ink-soft);
}
.empty .big-font { font-size: 40px; margin-bottom: 10px; }

